func testVeiculoManutencaoToOneSetOpVeiculoUsingVei(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a VeiculoManutencao
	var b, c Veiculo

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, veiculoManutencaoDBTypes, false, strmangle.SetComplement(veiculoManutencaoPrimaryKeyColumns, veiculoManutencaoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, veiculoDBTypes, false, strmangle.SetComplement(veiculoPrimaryKeyColumns, veiculoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, veiculoDBTypes, false, strmangle.SetComplement(veiculoPrimaryKeyColumns, veiculoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*Veiculo{&b, &c} {
		err = a.SetVei(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.Vei != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.VeiVeiculoManutencaos[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if a.VeiID != x.VeiID {
			t.Error("foreign key was wrong value", a.VeiID)
		}

		if exists, err := VeiculoManutencaoExists(ctx, tx, a.VeiID, a.ManID, a.VeimanItem); err != nil {
			t.Fatal(err)
		} else if !exists {
			t.Error("want 'a' to exist")
		}

	}
}

